other_ways.code:
try:
    coins = int(input("Coins? "))
    friends = int(input("Friends? "))
    share = coins // friends
except ValueError:
    print("not a number")
except ZeroDivisionError:
    print("nobody to share with")
else:
    print(share)
    print(coins % friends)

try:
    coins = int(input("Coins? "))
    friends = int(input("Friends? "))
except ValueError:
    print("not a number")
else:
    if friends == 0:
        print("nobody to share with")
    else:
        print(coins // friends)
        print(coins % friends)
